const makePirateWeaponSprite=(rows:string[])=>{const pixels:(string|null)[]=Array(256).fill(null),at=(x:number,y:number)=>rows[y]?.[x]||".",edgeTone=(x:number,y:number)=>{const neighbors=[[1,0],[-1,0],[0,1],[0,-1],[1,1],[-1,-1]].map(([dx,dy])=>at(x+dx,y+dy));if(neighbors.some(symbol=>symbol==="D"))return"#4d351f";if(neighbors.some(symbol=>symbol==="R"))return"#512a2d";if(neighbors.some(symbol=>symbol==="G"||symbol==="B"||symbol==="C"))return"#805a2a";return"#465256"};rows.slice(0,16).forEach((row,y)=>[...row.slice(0,16)].forEach((symbol,x)=>{pixels[y*16+x]=symbol==="K"?edgeTone(x,y):PIRATE_WEAPON_COLORS[symbol]||null}));return pixels};
