const makeWatchtowerBlocks=()=>{const blocks:StructureBlock[]=[],put=(x:number,y:number,z:number,state:string)=>blocks.push({id:`structure_${x}_${y}_${z}`,x,y,z,state});for(let x=1;x<=7;x++)for(let z=1;z<=7;z++)put(x,0,z,"minecraft:mossy_stone_bricks");for(const [x,z] of [[1,1],[1,7],[7,1],[7,7]])for(let y=1;y<=6;y++)put(x,y,z,"minecraft:oak_log[axis=y]");for(let x=1;x<=7;x++)for(let z=1;z<=7;z++)if(x===1||x===7||z===1||z===7)put(x,6,z,"minecraft:oak_planks");for(let x=0;x<=8;x++)for(let z=0;z<=8;z++)if(x===0||x===8||z===0||z===8)put(x,7,z,"minecraft:oak_stairs[facing=north,half=bottom,shape=straight,waterlogged=false]");for(let y=1;y<=4;y++){put(1,y,4,"minecraft:oak_planks");put(7,y,4,"minecraft:oak_planks")}put(4,1,4,"minecraft:lantern[hanging=false,waterlogged=false]");return blocks};
const watchtowerBlocks=resolveStructureConnections(makeWatchtowerBlocks());
