const clone = <T,>(value:T):T => JSON.parse(JSON.stringify(value));
const uid = (prefix="cube") => `${prefix}_${Math.random().toString(36).slice(2,9)}`;
const slug = (value:string) => value.toLowerCase().trim().replace(/[^a-z0-9_.-]+/g,"_").replace(/^_+|_+$/g,"")||"model";
const modelKind = (project:Project):ModelKind => project.kind || (project.id.includes("atm")?"furniture":"block");
const placementFootprint=(project:Project):Vec3=>(project.placementSize||[1,1,1]).map(value=>Math.max(1,Math.min(8,Math.round(Number(value)||1)))) as Vec3;
const placementCells=(size:Vec3)=>{const cells:Vec3[]=[];for(let y=0;y<size[1];y++)for(let z=0;z<size[2];z++)for(let x=0;x<size[0];x++)cells.push([x,y,z]);return cells};
const hasPlacementFootprint=(project:Project)=>modelKind(project)==="block"||modelKind(project)==="furniture";
const projectCategory=(project:Project)=>project.category||({item:"Tools & Weapons",block:"Blocks",furniture:"Furniture",mob:"Creatures",structure:"Structures"} as Record<ModelKind,string>)[modelKind(project)];
