const renderCubes=(project:Project):Cube[]=>modelKind(project)==="structure"?structureBlocksToCubes(project.structure?.blocks||[]):project.cubes;
const bonesFor=(project:Project):Bone[]=>project.bones?.length?project.bones:project.cubes.map(part=>({id:part.boneId||part.id,name:part.name,parentId:null,pivot:part.from.map((v,i)=>(v+part.to[i])/2) as Vec3}));
