function StructureEditor({project,layer,brush,onLayer,onBrush,onPaint,onFill,onResize}:{project:Project;layer:number;brush:string;onLayer:(value:number)=>void;onBrush:(value:string)=>void;onPaint:(x:number,z:number)=>void;onFill:()=>void;onResize:(size:Vec3)=>void}){
  const structure=project.structure!;
  return <section className="structure-builder">
    <header><div><span className="eyebrow">STRUCTURE MODE</span><h2>Block layer {layer+1} of {structure.size[1]}</h2></div><button onClick={onFill}>{brush==="minecraft:air"?"Clear":"Fill"} layer</button></header>
    <div className="structure-controls">
      <label>Y LAYER<input type="range" min="0" max={structure.size[1]-1} value={Math.min(layer,structure.size[1]-1)} onChange={event=>onLayer(Number(event.target.value))}/></label>
      <label>QUICK PALETTE<select value={BLOCK_OPTIONS.some(option=>option.state===brush)?brush:""} onChange={event=>onBrush(event.target.value)}><option value="" disabled>Custom Java state</option>{BLOCK_OPTIONS.map(option=><option key={option.state} value={option.state}>{option.label}</option>)}</select></label>
      <label className="structure-state">JAVA BLOCK STATE<input value={brush} onChange={event=>onBrush(event.target.value)} spellCheck={false} placeholder="minecraft:potted_blue_orchid"/></label>
      <div className="structure-size">{(["Width X","Height Y","Length Z"] as const).map((label,index)=><label key={label}>{label}<input type="number" min="1" max="64" value={structure.size[index]} onChange={event=>{const next=[...structure.size] as Vec3;next[index]=Math.max(1,Math.min(64,Number(event.target.value)||1));onResize(next)}}/></label>)}</div>
    </div>
    <div className="structure-grid" style={{gridTemplateColumns:`repeat(${structure.size[0]},1fr)`,aspectRatio:`${structure.size[0]}/${structure.size[2]}`}}>{Array.from({length:structure.size[0]*structure.size[2]},(_,index)=>{const x=index%structure.size[0],z=Math.floor(index/structure.size[0]),block=structure.blocks.find(item=>item.x===x&&item.y===layer&&item.z===z),style=block?blockStyle(block.state):null;return <button key={`${x}_${z}`} title={`${x}, ${layer}, ${z}${block?` · ${block.state}`:" · air"}`} onClick={()=>onPaint(x,z)} style={{background:style?.color||"#111713"}}><span>{block?"■":""}</span></button>})}</div>
    <footer><span>Paint any Minecraft 26.2 Java block state. Doors pair automatically; panes, fences, and stair corners connect to neighbors.</span><code>{structure.size.join(" × ")} · {structure.blocks.length} blocks</code></footer>
  </section>
}

